// Package core assembles a Surface app: the kernel (desk, commands, settings, marks,
// events), the selected modules and the embedded agent, behind one HTTP handler.
//
// An app's main (generated by `surface generate`) starts Substrate, imports its modules
// and hands this package what Substrate opened:
//
//	app, err := core.New(ctx, core.Options{Name: "desk", DataDir: dir, DB: db, Modules: surfaceModules, Assets: assets})
//	err = app.Start(ctx)
//	http.Serve(l, app.Handler())
//
// Everything else in the core is under core/internal, out of a module's reach: a module
// sees only the module package.
package core

import (
	"context"
	"database/sql"
	"io/fs"
	"log/slog"
	"net/http"

	"github.com/hollis-labs/surface/core/internal/api"
	"github.com/hollis-labs/surface/core/internal/kernel"
)

// Options are what an app gives the core.
type Options struct {
	// Name is the app's name: lower case letters, digits and dashes. Title is how a person
	// reads it.
	Name  string
	Title string
	// DataDir is the app's data directory.
	DataDir string
	// DB is the core database (Substrate's database module). When nil the core opens
	// <DataDir>/surface.db itself.
	DB  *sql.DB
	Log *slog.Logger
	// Modules are the module ids to start, in order. Nil starts every module compiled in.
	Modules []string
	// Assets is the built page. Nil serves the API only.
	Assets fs.FS
}

// App is a running Surface app.
type App struct {
	k        *kernel.App
	assets   fs.FS
	services []service
}

// service is a core service with a lifetime and routes (the agent).
type service interface {
	api.Mounter
	Close(ctx context.Context) error
}

// New assembles the app. Nothing is served and no module is started until Start.
func New(ctx context.Context, o Options) (*App, error) {
	k, err := kernel.New(ctx, kernel.Options{Name: o.Name, Title: o.Title, DataDir: o.DataDir, DB: o.DB, Log: o.Log, Modules: o.Modules})
	if err != nil {
		return nil, err
	}
	a := &App{k: k, assets: o.Assets}
	if err := a.addServices(ctx); err != nil {
		_ = k.Stop(ctx)
		return nil, err
	}
	return a, nil
}

// Start starts the modules.
func (a *App) Start(ctx context.Context) error { return a.k.Start(ctx) }

// Handler serves the app: its API, its modules' routes, its agent and its page.
func (a *App) Handler() http.Handler {
	ms := make([]api.Mounter, 0, len(a.services))
	for _, s := range a.services {
		ms = append(ms, s)
	}
	return api.Handler(a.k, a.assets, ms...)
}

// Stop stops the agent, then the modules, and closes the stores.
func (a *App) Stop(ctx context.Context) error {
	for _, s := range a.services {
		_ = s.Close(ctx)
	}
	return a.k.Stop(ctx)
}
